function ui(){const css=document.createElement('link');css.rel='stylesheet';css.href='analytics.css?v=20261026';document.head.append(css);const dialog=document.createElement('dialog');dialog.dataset.consentDialog='';dialog.setAttribute('aria-label','Configurar privacidad');dialog.innerHTML='<h2>Privacidad y cookies</h2><p>Las funciones esenciales siempre están activas.</p><label><input type="checkbox" name="analytics"> Estadísticas de uso (Google, Cloudflare y medición propia)</label><label><input type="checkbox" name="recordings"> Mapas de calor y grabaciones de Clarity, con información enmascarada</label><p><a href="privacidad.html">Política de privacidad y cookies</a></p><button type="button" data-save>Guardar preferencias</button> <button type="button" data-reject>Rechazar no esenciales</button> <button type="button" data-close>Cerrar</button>';document.body.append(dialog);dialog.querySelector('[data-save]').onclick=()=>decide(dialog.querySelector('[name=analytics]').checked,dialog.querySelector('[name=recordings]').checked);dialog.querySelector('[data-reject]').onclick=()=>decide(false,false);dialog.querySelector('[data-close]').onclick=()=>dialog.close();function configure(){dialog.querySelector('[name=analytics]').checked=!!consent?.analytics;dialog.querySelector('[name=recordings]').checked=!!consent?.recordings;dialog.showModal();}const settings=document.createElement('button');settings.type='button';settings.className='privacy-settings';settings.textContent='Privacidad y cookies';settings.onclick=configure;document.querySelector('footer')?.append(settings);if(!consent&&!privatePage){const banner=document.createElement('aside');banner.dataset.consentBanner='';banner.setAttribute('aria-label','Preferencias de privacidad');banner.innerHTML='<strong>Tu privacidad</strong><p>Con tu permiso medimos el uso de la web y, opcionalmente, grabamos sesiones enmascaradas. Puedes rechazarlo y seguir utilizando el club.</p><button type="button" data-accept>Aceptar</button> <button type="button" data-reject>Rechazar</button> <button type="button" data-config>Configurar</button> <a href="privacidad.html">Más información</a>';banner.querySelector('[data-accept]').onclick=()=>decide(true,true);banner.querySelector('[data-reject]').onclick=()=>decide(false,false);banner.querySelector('[data-config]').onclick=configure;document.body.append(banner);}document.querySelectorAll('form,input,textarea,[contenteditable],.club-whatsapp').forEach(n=>n.setAttribute('data-clarity-mask','true'));}
window.clubAnalytics={track,flush};window.addEventListener('club-analytics',e=>track(e.detail?.name,e.detail?.params));document.addEventListener('visibilitychange',()=>{if(document.hidden){heartbeat();void flush();}else activeAt=performance.now();});window.addEventListener('pagehide',()=>{heartbeat();void flush();});function heartbeat(){const now=performance.now(),ms=Math.min(30000,Math.max(0,now-activeAt));activeAt=now;if(enabled()&&Date.now()-lastActivity<60000&&ms>500)track('user_engagement',{active_ms:ms});}for(const type of ['pointerdown','keydown','scroll'])document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true});setInterval(()=>{if(!document.hidden)heartbeat();},30000);
