const searched=new WeakMap();function searchInput(input){if(!input)return;const now=Date.now();if(now-(searched.get(input)||0)<800)return;searched.set(input,now);track('site_search',{query_length:input.value.length});}document.addEventListener('search',e=>{if(e.target.matches('input[type=search]'))searchInput(e.target);},true);document.addEventListener('submit',e=>searchInput(e.target.querySelector('input[type=search]')),true);const videos=new WeakMap();function videoEvent(e){const v=e.target;if(!(v instanceof HTMLVideoElement))return;let state=videos.get(v);if(!state){state={started:false,progress:new Set()};videos.set(v,state);}if(e.type==='play'&&!state.started){state.started=true;track('video_start');}if(e.type==='timeupdate'&&v.duration>0)for(const percent of [25,50,75])if(v.currentTime/v.duration*100>=percent&&!state.progress.has(percent)){state.progress.add(percent);track('video_progress',{progress:percent});}if(e.type==='ended'){track('video_complete',{progress:100});videos.delete(v);}}for(const t of ['play','timeupdate','ended'])document.addEventListener(t,videoEvent,true);
